def ray_info(I):
    H,W=len(I),len(I[0]); bgv=Counter(x for r in I for x in r).most_common(1)[0][0]
    seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bgv and (i,j) not in seen:
                c=I[i][j]; st=[(i,j)]; seen.add((i,j)); pts=[]
                while st:
                    p=st.pop(); pts.append(p); 
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+di,p[1]+dj)
                        if 0<=q[0]<H and 0<=q[1]<W and I[q[0]][q[1]]==c and q not in seen:
                            seen.add(q); st.append(q)
                rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
                bb={(min(rs),min(cs)),(min(rs),max(cs)),(max(rs),min(cs)),(max(rs),max(cs))}
                miss=list(bb-set(pts))[0]
                mi=sum(p[0] for p in pts)/3; mj=sum(p[1] for p in pts)/3
                dr=1 if miss[0]>mi else -1; dc=1 if miss[1]>mj else -1
